import java.util.*;

class Solution {
  public List<Integer> shortestDistanceColor(int[] colors, int[][] queries) {
    int n = colors.length;
    int[][] dist = new int[4][n]; // distance from i to the nearest of each color
    for (int c = 1; c <= 3; c++) {
      Arrays.fill(dist[c], Integer.MAX_VALUE);
      for (int i = 0, last = -1; i < n; i++) {
        if (colors[i] == c) last = i;
        if (last >= 0) dist[c][i] = i - last;
      }
      for (int i = n - 1, last = -1; i >= 0; i--) {
        if (colors[i] == c) last = i;
        if (last >= 0) dist[c][i] = Math.min(dist[c][i], last - i);
      }
    }
    List<Integer> res = new ArrayList<>();
    for (int[] q : queries) res.add(dist[q[1]][q[0]] == Integer.MAX_VALUE ? -1 : dist[q[1]][q[0]]);
    return res;
  }
}
